{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-10-17/server.schema.json",
  "name": "io.github.aplaceforallmystuff/mcp-arr",
  "description": "MCP server for *arr media suite - Sonarr, Radarr, Lidarr, Prowlarr",
  "repository": {
    "url": "https://github.com/aplaceforallmystuff/mcp-arr",
    "source": "github"
  },
  "version": "1.6.3",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "mcp-arr-server",
      "version": "1.6.3",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Sonarr server URL",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "SONARR_URL"
        },
        {
          "description": "Sonarr API key",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "SONARR_API_KEY"
        },
        {
          "description": "Radarr server URL",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "RADARR_URL"
        },
        {
          "description": "Radarr API key",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "RADARR_API_KEY"
        },
        {
          "description": "Lidarr server URL",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "LIDARR_URL"
        },
        {
          "description": "Lidarr API key",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "LIDARR_API_KEY"
        },
        {
          "description": "Prowlarr server URL",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "PROWLARR_URL"
        },
        {
          "description": "Prowlarr API key",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "PROWLARR_API_KEY"
        }
      ]
    }
  ]
}
